import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadOswald = makeLoadFont('Oswald');
const loadPlayfair = makeLoadFont('PlayfairDisplay');

const { fontFamily: oswaldFamily } = loadOswald();
const { fontFamily: playfairFamily } = loadPlayfair();



export type TheBigSwingProps = Record<string, any>;

const TheBigSwing: React.FC<TheBigSwingProps> = ({
  backgroundColor = "#2A0404", // Deep Red Base
  transparentBackground = false,
  durationInSeconds = 10,
  primaryGold = "#F6D365",
  secondaryDarkGold = "#B8860B",
  accentRed = "#600000",
  titleWord1 = "THE",
  titleWord2 = "BIG",
  titleWord3 = "SWING",
  subtitle = "BIG BAND DANCE NIGHT",
  guestVocalist = "WITH GUEST VOCALIST CLARE THURSFIELD",
  dateText = "SUNDAY 26 APRIL • 7:30 PM",
  venueText = "THE ROYAL BRITISH LEGION, HALL CROFT BEESTON NOTTINGHAM NG9 1EL",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height);

  // Parser safety for transparent background
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // --- Animations ---

  // Decorative Elements Animations
  const borderProgress = spring({
    frame: frame - 5,
    fps,
    config: { damping: 20 },
  });
  const borderOpacity = interpolate(borderProgress, [0, 1], [0, 0.6]);
  const borderScale = interpolate(borderProgress, [0, 1], [0.95, 1]);

  // Top Info
  const topInfoProgress = spring({
    frame: frame - 15,
    fps,
    config: { damping: 14 },
  });
  const topInfoY = interpolate(topInfoProgress, [0, 1], [-50, 0]);
  const topInfoOpacity = interpolate(topInfoProgress, [0, 1], [0, 1]);

  // "THE"
  const theProgress = spring({
    frame: frame - 25,
    fps,
    config: { damping: 12 },
  });
  const theScale = interpolate(theProgress, [0, 1], [0.5, 1]);
  const theOpacity = interpolate(theProgress, [0, 1], [0, 1]);

  // "BIG"
  const bigProgress = spring({
    frame: frame - 35,
    fps,
    config: { damping: 10, mass: 1.5 },
  });
  const bigScale = interpolate(bigProgress, [0, 1], [1.5, 1]);
  const bigOpacity = interpolate(bigProgress, [0, 1], [0, 1]);

  // "SWING"
  const swingProgress = spring({
    frame: frame - 45,
    fps,
    config: { damping: 12 },
  });
  const swingY = interpolate(swingProgress, [0, 1], [100, 0]);
  const swingOpacity = interpolate(swingProgress, [0, 1], [0, 1]);

  // Continuous swinging pendulum effect based on pure sine wave
  // Starts straight, swings back and forth
  const swingAngle = Math.sin(frame * 0.05) * 8;

  // Bottom Info
  const bottomInfoProgress = spring({
    frame: frame - 60,
    fps,
    config: { damping: 14 },
  });
  const bottomInfoY = interpolate(bottomInfoProgress, [0, 1], [50, 0]);
  const bottomInfoOpacity = interpolate(bottomInfoProgress, [0, 1], [0, 1]);

  // Sunburst Background Effect
  const rays = 18;
  const rayElements = Array.from({ length: rays }).map((_, i) => {
    const rotationBase = (360 / rays) * i;
    // Continuous rotation for vintage spotlight feel
    const animatedRotation = rotationBase + frame * 0.15;
    return (
      <div
        key={i}
        style={{
          position: "absolute",
          width: width * 2,
          height: height * 0.08,
          backgroundColor: primaryGold,
          opacity: 0.03,
          top: height / 2 - (height * 0.08) / 2,
          left: width / 2 - width,
          transform: `rotate(${animatedRotation}deg)`,
          transformOrigin: "center center",
          transition: "none",
        }}
      />
    );
  });

  // Reusable Art Deco Line Separator
  const DecoLine = ({ delay }: { delay: number }) => {
    const widthProgress = spring({
      frame: frame - delay,
      fps,
      config: { damping: 14 },
    });
    const w = interpolate(widthProgress, [0, 1], [0, 100]); // percentage of parent
    const alpha = interpolate(widthProgress, [0, 1], [0, 1]);
    return (
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          width: "100%",
          margin: `${s * 0.03}px 0`,
          opacity: alpha,
          transition: "none",
        }}
      >
        <div
          style={{ width: `${w / 2.5}%`, height: 2, backgroundColor: primaryGold }}
        />
        <div
          style={{
            width: s * 0.02,
            height: s * 0.02,
            backgroundColor: secondaryDarkGold,
            margin: "0 15px",
            transform: "rotate(45deg)",
          }}
        />
        <div
          style={{ width: `${w / 2.5}%`, height: 2, backgroundColor: primaryGold }}
        />
      </div>
    );
  };

  // 3D Marquee Text Shadow for primary words
  const marqueeShadow = `
    2px 2px 0px ${accentRed},
    4px 4px 0px ${accentRed},
    6px 6px 0px ${accentRed},
    8px 8px 0px ${secondaryDarkGold},
    10px 10px 0px rgba(0,0,0,0.6)
  `;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      {/* Background Vignette & Sunburst */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: `radial-gradient(circle at center, transparent 30%, ${accentRed} 120%)`,
          opacity: 0.8,
          transition: "none",
        }}
      />
      {rayElements}

      {/* Art Deco Borders */}
      <div
        style={{
          position: "absolute",
          inset: "4%",
          border: `4px solid ${primaryGold}`,
          opacity: borderOpacity,
          transform: `scale(${borderScale})`,
          transition: "none",
          pointerEvents: "none",
        }}
      />
      <div
        style={{
          position: "absolute",
          inset: "5.5%",
          border: `1.5px solid ${primaryGold}`,
          opacity: borderOpacity * 0.5,
          transform: `scale(${borderScale})`,
          transition: "none",
          pointerEvents: "none",
        }}
      />

      {/* Main Content Layout */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "center",
          width: "100%",
          height: "100%",
          paddingTop: height * 0.15,
          paddingBottom: height * 0.1,
          paddingLeft: "10%",
          paddingRight: "10%",
          boxSizing: "border-box",
          textAlign: "center",
          zIndex: 10,
        }}
      >
        {/* Top Info */}
        <div
          style={{
            fontFamily: playfairFamily,
            color: primaryGold,
            fontSize: s * 0.045,
            letterSpacing: "0.15em",
            opacity: topInfoOpacity,
            transform: `translateY(${topInfoY}px)`,
            textTransform: "uppercase",
            transition: "none",
          }}
        >
          {dateText}
        </div>

        <DecoLine delay={20} />

        {/* Title: THE */}
        <div
          style={{
            fontFamily: oswaldFamily,
            color: primaryGold,
            fontSize: s * 0.09,
            lineHeight: 1,
            letterSpacing: "0.2em",
            opacity: theOpacity,
            transform: `scale(${theScale})`,
            marginBottom: s * 0.02,
            transition: "none",
          }}
        >
          {titleWord1}
        </div>

        {/* Title: BIG */}
        <div
          style={{
            fontFamily: oswaldFamily,
            color: primaryGold,
            fontSize: s * 0.28,
            lineHeight: 0.85,
            letterSpacing: "0.02em",
            opacity: bigOpacity,
            transform: `scale(${bigScale})`,
            textShadow: marqueeShadow,
            zIndex: 2,
            transition: "none",
          }}
        >
          {titleWord2}
        </div>

        {/* Title: SWING (with continuous pendulum effect) */}
        <div
          style={{
            opacity: swingOpacity,
            transform: `translateY(${swingY}px)`,
            zIndex: 3,
            marginTop: s * 0.02,
            transition: "none",
          }}
        >
          <div
            style={{
              fontFamily: oswaldFamily,
              color: primaryGold,
              fontSize: s * 0.22,
              lineHeight: 0.9,
              letterSpacing: "0.05em",
              textShadow: marqueeShadow,
              transformOrigin: "center top",
              transform: `rotate(${swingAngle}deg)`,
              transition: "none",
            }}
          >
            {titleWord3}
          </div>
        </div>

        <DecoLine delay={55} />

        {/* Bottom Info / Subtitle */}
        <div
          style={{
            fontFamily: playfairFamily,
            color: primaryGold,
            fontSize: s * 0.045,
            letterSpacing: "0.2em",
            opacity: bottomInfoOpacity,
            transform: `translateY(${bottomInfoY}px)`,
            textTransform: "uppercase",
            marginBottom: s * 0.02,
            transition: "none",
          }}
        >
          {subtitle}
        </div>

        {/* Guest Vocalist */}
        <div
          style={{
            fontFamily: playfairFamily,
            color: primaryGold,
            fontSize: s * 0.035,
            letterSpacing: "0.15em",
            opacity: bottomInfoOpacity,
            transform: `translateY(${bottomInfoY}px)`,
            textTransform: "uppercase",
            marginBottom: s * 0.02,
            transition: "none",
          }}
        >
          {guestVocalist}
        </div>

        {/* Venue Info */}
        <div
          style={{
            fontFamily: playfairFamily,
            color: secondaryDarkGold,
            fontSize: s * 0.03,
            letterSpacing: "0.1em",
            lineHeight: 1.4,
            padding: `0 ${s * 0.05}px`,
            opacity: bottomInfoOpacity,
            transform: `translateY(${bottomInfoY}px)`,
            textTransform: "uppercase",
            transition: "none",
          }}
        >
          {venueText}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default TheBigSwing;